import sys

class Product:
    def __init__(self, name, price, seller):
        self.name = name
        self.price = price
        self.seller = seller

    def print_details(self):
        pass

class NewProduct(Product):
    def print_details(self):
        price_str = f"{self.price:.2f}" if self.price == int(self.price) else str(self.price)
        print(f"New Product: {self.name}, Price: ${price_str}, Seller: {self.seller}")

class UsedProduct(Product):
    def __init__(self, name, price, seller, condition):
        super().__init__(name, price, seller)
        self.condition = condition

    def print_details(self):
        price_str = f"{self.price:.2f}" if self.price == int(self.price) else str(self.price)
        print(f"Used Product: {self.name}, Price: ${price_str}, Seller: {self.seller}, Condition: {self.condition}")

def main():
    for line in sys.stdin:
        line = line.strip()
        if not line:
            continue
        parts = line.split(', ')
        if len(parts) == 3:
            name, price, seller = parts
            product = NewProduct(name, float(price), seller)
            product.print_details()
        elif len(parts) == 4:
            name, price, seller, condition = parts
            product = UsedProduct(name, float(price), seller, condition)
            product.print_details()

if __name__ == "__main__":
    main()
